<template><div class="page"><div class="page-heading"><div><h1>系统管理</h1><p>管理用户、角色、权限及系统操作日志。</p></div></div><el-tabs v-model="active"><el-tab-pane label="用户管理" name="users"><el-card class="panel-card"><el-table :data="users" stripe><el-table-column prop="username" label="用户名" /><el-table-column prop="nickname" label="姓名" /><el-table-column prop="department" label="部门" /><el-table-column prop="roles" label="角色"><template #default="{ row }"><el-tag v-for="role in row.roles || []" :key="role" size="small" class="role-tag">{{ role }}</el-tag></template></el-table-column><el-table-column prop="status" label="状态"><template #default="{ row }"><el-tag type="success">{{ row.status }}</el-tag></template></el-table-column></el-table></el-card></el-tab-pane><el-tab-pane label="角色与权限" name="roles"><el-card class="panel-card"><div class="role-grid"><div v-for="item in roleList" :key="item.name" class="role-card"><div class="role-title"><el-tag :type="item.type">{{ item.name }}</el-tag><b>{{ item.label }}</b></div><p>{{ item.permissions.join(' · ') }}</p></div></div></el-card></el-tab-pane><el-tab-pane label="操作日志" name="logs"><el-card class="panel-card"><el-table :data="logs" stripe><el-table-column prop="time" label="时间" width="180" /><el-table-column prop="operator" label="操作人" width="120" /><el-table-column prop="module" label="模块" width="130" /><el-table-column prop="action" label="操作内容" /><el-table-column prop="result" label="结果"><template #default="{ row }"><el-tag type="success">{{ row.result }}</el-tag></template></el-table-column><el-table-column prop="ip" label="IP地址" /></el-table></el-card></el-tab-pane></el-tabs></div></template>
<script setup>
import { onMounted, ref } from 'vue'; import { api } from '../api'; const active = ref('users'); const users = ref([]); const logs = ref([]); const roleList = [{ name: 'ADMIN', label: '系统管理员', type: 'danger', permissions: ['用户管理', '角色管理', '系统配置', '操作日志'] }, { name: 'MANAGER', label: '部门负责人', type: 'warning', permissions: ['查看部门申请', '审批采购申请'] }, { name: 'PURCHASER', label: '采购人员', type: 'primary', permissions: ['供应商管理', '创建采购订单'] }, { name: 'WAREHOUSE', label: '仓库管理员', type: 'success', permissions: ['入库确认', '库存管理'] }, { name: 'EMPLOYEE', label: '普通员工', type: 'info', permissions: ['创建采购申请', '查看个人申请'] }]; onMounted(async () => { const u = await api.users(); users.value = u?.records || u?.data?.records || u || []; const l = await api.logs(); logs.value = l?.records || l?.data?.records || l || [] })
</script>
